'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var dindexOfLessThanEqual = tryRequire( resolve( __dirname, './../lib/ndarray.native.js' ) );
var opts = {
	'skip': ( dindexOfLessThanEqual instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dindexOfLessThanEqual, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', opts, function test( t ) {
	t.strictEqual( dindexOfLessThanEqual.length, 5, 'has expected arity' );
	t.end();
});

tape( 'the function returns the index of the first element in a strided array which is less than or equal to a provided search element', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ] );

	actual = dindexOfLessThanEqual( x.length, 3.0, x, 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if every indexed element in the array is greater than the search element', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 2.0, 2.0, 2.0 ] );

	actual = dindexOfLessThanEqual( x.length, 1.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if a provided `N` parameter is less than or equal to zero', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 1.0, 2.0, 3.0 ] );

	actual = dindexOfLessThanEqual( 0, 2.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dindexOfLessThanEqual( -1, 2.0, x, 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function returns `-1` if comparisons involve `NaN` values', opts, function test( t ) {
	var actual;

	actual = dindexOfLessThanEqual( 2, NaN, new Float64Array( [ 0.0, 1.0 ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	actual = dindexOfLessThanEqual( 2, 0.0, new Float64Array( [ NaN, NaN ] ), 1, 0 );
	t.strictEqual( actual, -1, 'returns expected value' );

	t.end();
});

tape( 'the function treats `-0` and `+0` as equal', opts, function test( t ) {
	var actual;

	actual = dindexOfLessThanEqual( 1, -0.0, new Float64Array( [ 0.0 ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = dindexOfLessThanEqual( 1, 0.0, new Float64Array( [ -0.0 ] ), 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		2.0, // 0
		9.0,
		2.0, // 1
		9.0,
		1.0  // 2
	]);

	actual = dindexOfLessThanEqual( 3, 1.0, x, 2, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports an `x` offset', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		9.0,
		2.0, // 0
		9.0,
		2.0, // 1
		9.0,
		1.0  // 2
	]);

	actual = dindexOfLessThanEqual( 3, 1.0, x, 2, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});

tape( 'the function supports a negative `x` stride', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array( [ 2.0, 2.0, 2.0, 2.0, 1.0, 2.0 ] );

	actual = dindexOfLessThanEqual( x.length, 1.0, x, -1, x.length-1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

tape( 'the function supports complex access patterns', opts, function test( t ) {
	var actual;
	var x;

	x = new Float64Array([
		9.0,
		2.0, // 0
		9.0,
		2.0, // 1
		9.0,
		1.0  // 2
	]);

	actual = dindexOfLessThanEqual( 3, 1.0, x, 2, 1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	t.end();
});
